function pipelineCost(jobs, failsAt) {
  var passed = {};
  var total = 0;
  var lines = [];
  for (var k = 0; k < jobs.length; k++) {
    var job = jobs[k];
    var blocked = job.needs.some(function (n) { return passed[n] === false; });
    if (blocked) {
      passed[job.name] = false;
      lines.push('SKIP    ' + job.name + ' (+0)');
      continue;
    }
    total += job.min;
    var ok = job.name !== failsAt;
    passed[job.name] = ok;
    lines.push((ok ? 'PASS    ' : 'FAIL    ') + job.name + ' (+' + job.min + ')');
  }
  lines.push('TOTAL ' + total + ' min');
  return lines.join('\n');
}

var gated = [
  { name: 'lint', min: 2, needs: [] },
  { name: 'unit', min: 3, needs: ['lint'] },
  { name: 'build', min: 3, needs: ['lint'] },
  { name: 'e2e', min: 25, needs: ['unit', 'build'] }
];
var flat = [
  { name: 'lint', min: 2, needs: [] },
  { name: 'unit', min: 3, needs: [] },
  { name: 'build', min: 3, needs: [] },
  { name: 'e2e', min: 25, needs: [] }
];
console.log('GATED, lint fails:');
console.log(pipelineCost(gated, 'lint'));
console.log('FLAT, lint fails:');
console.log(pipelineCost(flat, 'lint'));
